<?php declare(strict_types=1);$components=dirname(__DIR__,2).'/components';$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');ob_start();$breadcrumbItems=[['label'=>'Community Actions','url'=>'/community-actions'],['label'=>$c->propertyDisplayName,'url'=>'/community-actions/'.$c->propertySlug],['label'=>'Credit Card Purchases','url'=>'/community-actions/'.$c->propertySlug.'/credit-card-purchases'],['label'=>'Credit Card Purchase','current'=>true]];require $components.'/breadcrumb.php';$heading='Credit Card Purchase';$description=$c->propertyDisplayName;$eyebrow='Credit Card Purchases';$actionsHtml='';require $components.'/page-header.php';if($success!==''):?><div class="alert gateway-alert gateway-alert--success" role="status"><?=$e($success)?></div><?php endif;if($error!==''):?><div class="alert gateway-alert gateway-alert--danger" role="alert"><?=$e($error)?></div><?php endif?><span class="gateway-status <?=$purchase['receipt_status']==='attached'?'gateway-status--success':'gateway-status--warning'?>"><?=$purchase['receipt_status']==='attached'?'Receipt Attached':'Receipt Missing'?></span><section class="gateway-card gateway-review-record mt-3"><div class="gateway-card__body"><h2 class="gateway-card__title">Purchase Summary</h2><dl class="row gateway-review-record__fields"><dt class="col-sm-4 gateway-review-record__label">Card Last Four</dt><dd class="col-sm-8 gateway-review-record__value">•••• <?=$e($purchase['card_last_four'])?></dd><dt class="col-sm-4 gateway-review-record__label">Date of Purchase</dt><dd class="col-sm-8 gateway-review-record__value"><?=$e($purchase['purchase_date'])?></dd><dt class="col-sm-4 gateway-review-record__label">Amount</dt><dd class="col-sm-8 gateway-review-record__value"><?=$e(\NpmGateway\Support\CurrencyFormatter::usd((string)$purchase['amount']))?></dd><dt class="col-sm-4 gateway-review-record__label">Purchased By</dt><dd class="col-sm-8 gateway-review-record__value"><?=$e($purchase['purchased_by_name'